"""
Simple test to understand the _get_logprobs function structure.
"""
import sys
sys.path.insert(0, '.')

# Read the sampler.py file to understand the _get_logprobs function
with open('vllm/model_executor/layers/sampler.py', 'r') as f:
    content = f.read()

# Find the _get_logprobs function
import re
match = re.search(r'def _get_logprobs\(.*?\n(?:.*?\n)*?^(?=def |\Z)', content, re.MULTILINE)
if match:
    print("Found _get_logprobs function:")
    print("=" * 60)
    lines = match.group(0).split('\n')
    for i, line in enumerate(lines[:100], 1):
        print(f"{i:4d}: {line}")
    print("=" * 60)
else:
    print("Function not found")

# Look for performance issues in the code
print("\n\nAnalyzing potential performance issues:")
print("=" * 60)

# Check for CPU/GPU transfers
cpu_transfers = []
for i, line in enumerate(content.split('\n'), 1):
    if '.cpu()' in line or '.to(' in line:
        cpu_transfers.append((i, line.strip()))

if cpu_transfers:
    print(f"\nFound {len(cpu_transfers)} potential CPU/GPU transfers:")
    for line_num, line in cpu_transfers[:10]:
        print(f"  Line {line_num}: {line}")

# Check for tensor operations
tensor_ops = []
for i, line in enumerate(content.split('\n'), 1):
    if 'torch.' in line and ('tolist()' in line or 'item()' in line):
        tensor_ops.append((i, line.strip()))

if tensor_ops:
    print(f"\nFound {len(tensor_ops)} tensor-to-python conversions:")
    for line_num, line in tensor_ops[:10]:
        print(f"  Line {line_num}: {line}")

# Check for list/dict operations
list_ops = []
for i, line in enumerate(content.split('\n'), 1):
    if '.extend(' in line or '.append(' in line:
        list_ops.append((i, line.strip()))

if list_ops:
    print(f"\nFound {len(list_ops)} list operations:")
    for line_num, line in list_ops[:10]:
        print(f"  Line {line_num}: {line}")

